/* Inner West Sydney Plumbers
   Part 1: small page behaviours (menu, quote form).
   Part 2: the 3D pipe run that the page scrolls along.
   The 3D is progressive enhancement only. The page is complete without it.
   Three.js and GSAP load from pinned CDN builds after first paint. */

/* ---------- Part 1: page behaviours ---------- */
(function () {
  'use strict';
  var d = document;
  function ready(fn) { if (d.readyState === 'loading') { d.addEventListener('DOMContentLoaded', fn); } else { fn(); } }

  ready(function () {
  var check = d.getElementById('iw-navcheck');
  var nav = d.querySelector('.iw-nav');
  if (check && nav) {
    nav.addEventListener('click', function (e) {
      if (e.target.closest && e.target.closest('a')) { check.checked = false; }
    });
    d.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { check.checked = false; }
    });
  }

  var form = d.getElementById('iw-quote-form');
  if (form) {
    var status = form.querySelector('.iw-form-status');
    form.addEventListener('submit', function (e) {
      e.preventDefault();
      var endpoint = form.getAttribute('data-endpoint');
      var first = (form.elements.name.value || '').trim().split(' ')[0];
      if (!endpoint) {
        status.textContent = 'Thanks' + (first ? ', ' + first : '') + '. This form is not connected to an inbox yet, so nothing has been sent. Call 1300 096 668 and we will sort it out now.';
        return;
      }
      var btn = form.querySelector('button[type="submit"]');
      btn.disabled = true;
      status.textContent = 'Sending your request.';
      fetch(endpoint, { method: 'POST', body: new FormData(form) }).then(function (r) {
        if (!r.ok) { throw new Error('send failed'); }
        form.reset();
        status.textContent = 'Request sent. We will call you back shortly.';
      }).catch(function () {
        status.textContent = 'That did not send. Please call 1300 096 668 instead.';
      }).then(function () { btn.disabled = false; });
    });
  }
  });
})();

