    collar(world, E1.x + 1.8, E1.y + 1.3, DX, 'orange');
    collar(world, E1.x - 1.8, E1.y - 1.3, DX, 'slate');
    collar(world, E2.x + 1.8, E2.y + 1.3, DX, 'orange');
